import json,pathlib
b=pathlib.Path('/tmp/objective-recovery-runs/u519/packet/abba-oversubscription')
for n in ['screen.json','qualify.json']:
 d=json.loads((b/n).read_text()); print('\n',n)
 for x in d['looks']:
  print(x['route'], 'rowkeys',list(x.get('row',{}).keys()))
  # walk key names matching time/busy
  def walk(o,p=''):
   if isinstance(o,dict):
    for k,v in o.items():
     if any(t in k.lower() for t in ('resident','service','busy','cpu','elapsed','lifecycle','outer')) and not isinstance(v,(dict,list)):
      print(' ',p+k,repr(v)[:200])
     walk(v,p+k+'.')
   elif isinstance(o,list):
    for i,v in enumerate(o): walk(v,p+str(i)+'.')
  walk(x)
